INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(27001, 'Romans 8:18', 'Romans', 8, 18, '&nbsp;زما په دې باور دے چې دا کوم تکليفونه چې مونږ يې اوس زغمو د هغه جلال په مقابله کښې هيڅ نۀ دى کوم چې مونږ ته ملاوېدونکے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27002, 'Romans 8:19', 'Romans', 8, 19, '&nbsp;ځکه چې ټول کائنات د خُدائ پاک د بچو د ښکاره کېدو دپاره په ډېر شوق سره په طمع دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27003, 'Romans 8:20', 'Romans', 8, 20, '&nbsp;ځکه چې مخلوقات د فنا تابع کړے شول، په خپله رضا نه بلکې د هغه خُدائ پاک په رضا چا چې هغوئ ته دا اُميد ورکړو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27004, 'Romans 8:21', 'Romans', 8, 21, '&nbsp;چې مخلوقات به په خپله يوه ورځ د فنا کېدو نه آزاد شى او د خُدائ پاک د بچو د جلال په آزادۍ کښې به شامل شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27005, 'Romans 8:22', 'Romans', 8, 22, '&nbsp;مونږ په دې پوهه شو چې ټول کائنات تر اوسه پورې د ماشوم د زيږېدو د درد په شان زبيرګى کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27006, 'Romans 8:23', 'Romans', 8, 23, '&nbsp;صرف کائنات نه بلکې مونږ هم په زبيرګو کښې يُو چې راته د روح اوله مېوه مِلاو شوې ده، او مونږ په دې اِنتظار کښې يُو چې خُدائ پاک مو په خپل زوئ والى کښې قبول کړى او زمونږ ټول وجود ته خلاصون ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27007, 'Romans 8:24', 'Romans', 8, 24, '&nbsp;نو چې مونږ خلاصون وموندو نو هغه اُميد راته مِلاو شو، خو اوس هغه اُميد چې مونږ ته مِلاو شو نو بيا انتظار د څۀ دپاره کوُو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27008, 'Romans 8:25', 'Romans', 8, 25, '&nbsp;خو کۀ چرې مونږ د هغه څيز اُميد کوُو څۀ چې مونږ نۀ وينو نو مونږ به په صبر سره د دې انتظار وکړُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27009, 'Romans 8:26', 'Romans', 8, 26, '&nbsp;روحُ القُدس هم په دې شان زمونږ په کمزورتياو کښې زمونږ مدد کوى. مونږ په دې هم نۀ پوهيږو چې دُعا څنګه کول په کار دى خو روحُ القُدس په اسويلو کښې زمونږ داسې شفاعت کوى چې په لفظونو کښې نۀ شى بيانېدلے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27010, 'Romans 8:27', 'Romans', 8, 27, '&nbsp;او خُدائ پاک څوک چې د زړُونو په رازونو پوهه دے، هغۀ ته دا معلومه ده چې د روحُ القُدس سوچ څۀ دے ځکه چې روحُ القُدس د مقدسينو دپاره د خُدائ پاک د مرضۍ په مطابق شفاعت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27011, 'Romans 8:28', 'Romans', 8, 28, '&nbsp;مونږ ته پته ده څوک چې د خُدائ پاک سره مينه کوى د هغه خلقو د ښېګړې دپاره هر څۀ په شريکه کار کوى يعنې کوم خلق چې د هغۀ د ارادې په مطابق رابللے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27012, 'Romans 8:29', 'Romans', 8, 29, '&nbsp;ځکه چې خُدائ پاک هغوئ د مخکښې نه پېژندل او هغوئ يې د مخکښې نه مقرر کړى وُو، چې دوئ دې د هغۀ د زوئ په شان شى، ترڅو چې د هغۀ زوئ په دې ټولو وروڼو کښې اول زوئ وګرځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27013, 'Romans 8:30', 'Romans', 8, 30, '&nbsp;او هم دا د مخکښې نه مقرر کړے شوى هم وُو او هغه څوک چې خُدائ رابللى دى، هغه يې صادقان کړى هم دى، او څوک چې هغۀ صادقان کړى دى، هغوئ ته يې خپل جلال هم ورکړے دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27014, 'Romans 8:31', 'Romans', 8, 31, '&nbsp;نو بيا مونږ د دې خبرو په حق کښې څۀ وئيلے شُو؟ کۀ خُدائ پاک زمونږ په طرف دے نو بيا زمونږ مخالف څوک کېدے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27015, 'Romans 8:32', 'Romans', 8, 32, '&nbsp;هغۀ خو خپل زوئ هم پرې نۀ ښودو او زمونږ دپاره يې د قربانۍ دپاره پېش کړو، نو بيا د دې سره به مونږ ته نور څيزونه رانۀ کړى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27016, 'Romans 8:33', 'Romans', 8, 33, '&nbsp;د خُدائ پاک په غوره کسانو څوک اِلزام لګولے شى؟ ځکه چې په خپله خُدائ پاک مونږ صادق کړى يُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27017, 'Romans 8:34', 'Romans', 8, 34, '&nbsp;نو بيا څوک مونږ مجرمان کولے شى؟ هيڅوک نه، ځکه چې عيسىٰ مسيح زمونږ دپاره مړ شو او زمونږ دپاره د مړو نه بيا راژوندے شو او هغه د خُدائ پاک ښى لاس ته ناست دے او بې‌شکه چې زمونږ شفاعت کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27018, 'Romans 8:35', 'Romans', 8, 35, '&nbsp;نو بيا به څوک د مسيح د مينې نه مونږ جدا کړى؟ سختې يا مصيبتونه، ظلم، زياتے، لوږه، بربنډتوب، خطره يا مرګ داسې کولے شى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27019, 'Romans 8:36', 'Romans', 8, 36, '&nbsp;لکه چې په صحيفو کښې ليکلى دى چې، ”مونږ ستا دپاره ټوله ورځ د مرګ سره مخ کيږُو، د خلقو په نظر کښې مونږ د حلالونکو ګډو په شان ګڼلے کيږُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27020, 'Romans 8:37', 'Romans', 8, 37, '&nbsp;خو نه، د دې هر څۀ باوجود ټوله کاميابى د عيسىٰ مسيح په وسيله زمونږ ده څوک چې مونږ سره مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27021, 'Romans 8:38', 'Romans', 8, 38, '&nbsp;زۀ په دې پوره يقين ساتم چې نۀ مرګ او نۀ ژوندون، نۀ فرښتې، نۀ نور آسمانى حاکمان، نۀ اوسنى او نۀ راتلونکى څيزونه، نۀ قوتونه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27022, 'Romans 8:39', 'Romans', 8, 39, '&nbsp;په آسمان کښې او نۀ په زمکه او نۀ په ټول کائنات کښې داسې څۀ څيز شته چې مونږ د خُدائ پاک د مينې نه جدا کولے شى، کومه چې په مالِک عيسىٰ مسيح کښې مونږ ته مِلاو شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27023, 'Romans 9:1', 'Romans', 9, 1, '&nbsp;زۀ په مسيح کښې رښتيا وايم، دروغ نۀ وايم، او زما خپل ضمير د روحُ القُدس په وسيله د دې تصديق کوى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27024, 'Romans 9:2', 'Romans', 9, 2, '&nbsp;زما په زړۀ کښې ډېر لوئ غم او نۀ ختمېدونکے درد دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27025, 'Romans 9:3', 'Romans', 9, 3, '&nbsp;ځکه چې زما دا خواهش دے چې زۀ دې د خپلو خلقو او د انسانى فطرت په مطابق چې زما رشته‌دار دى د هغوئ د خاطره لعنتى شم او د دوئ دپاره دې زۀ د مسيح نه جدا شم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27026, 'Romans 9:4', 'Romans', 9, 4, '&nbsp;هغوئ بنى اِسرائيليان دى او هغوئ د خُدائ پاک بچى بللے شوى دى او ورته جلال، وعدې، شريعت، عبادت او لوظونه ورکړے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27027, 'Romans 9:5', 'Romans', 9, 5, '&nbsp;اِبراهيم، اِسحاق او يعقوب د هغوئ پلار نيکۀ دى او په انسانى لحاظ سره د هغوئ نه مسيح هم پېدا دے. خُدائ پاک چې د ټولو بادشاه دے د هغۀ نوم دې د تل دپاره مبارک وى، آمين.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27028, 'Romans 9:6', 'Romans', 9, 6, '&nbsp;ښه نو بيا خُدائ پاک د بنى اِسرائيلو سره په خپله وعده پوره کولو کښې ناکامه شو؟ نه، خبره داسې نۀ ده ځکه چې ټول بنى اِسرائيل په حقيقت کښې د خُدائ غوره شوى خلق نۀ دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27029, 'Romans 9:7', 'Romans', 9, 7, '&nbsp;او نۀ د اِبراهيم ټول اولاد د خُدائ پاک رښتينى بچى دى، خو صحيفې وائى چې، ”هم د اِسحاق نه به ستا نسل قائم وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27030, 'Romans 9:8', 'Romans', 9, 8, '&nbsp;مطلب دا چې د اِبراهيم په نسل کښې ټول د خُدائ پاک حقيقى بچى نۀ دى، خو صرف د خُدائ د وعدې په مطابق پېدا شوى د اِبراهيم اولاد بللے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27031, 'Romans 9:9', 'Romans', 9, 9, '&nbsp;ځکه چې وعده داسې شوې وه چې، ”تقريباً يو کال وروستو به زۀ تا ته واپس راشم او په دې وخت کښې به د ساره زوئ شوے وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27032, 'Romans 9:10', 'Romans', 9, 10, '&nbsp;او دا زوئ زمونږ نيکۀ اِسحاق دے. کله چې هغۀ د رِبقې سره وادۀ وکړو نو د هغې دوه غبرګونى زامن وشُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27033, 'Romans 9:11', 'Romans', 9, 11, '&nbsp;نو رِبقې ته د هغوئ د زيږېدو نه مخکښې ووئيلے شول چې په هغه وخت کښې چې هغوئ لا هيڅ ښۀ يا بد نۀ وُو کړى، خو بيا هم د دې دپاره چې د خُدائ پاک هغه مقرر شوے مقصد تر سره شى کوم چې د عمل په وسيله نه بلکې د خُدائ پاک په بلنه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27034, 'Romans 9:12', 'Romans', 9, 12, '&nbsp;نو خُدائ پاک هغې ته وئيلى وُو چې، ”مشر به د کشر خِدمت کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27035, 'Romans 9:13', 'Romans', 9, 13, '&nbsp;څنګه چې دا په صحيفو کښې ليکلى دى چې، ”ما يعقوب سره مينه وکړه او عِيسو ما رد کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27036, 'Romans 9:14', 'Romans', 9, 14, '&nbsp;نو په دې کښې مونږ څۀ ووايو؟ ولې خُدائ پاک بې‌اِنصافه دے څۀ؟ هيڅکله نه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27037, 'Romans 9:15', 'Romans', 9, 15, '&nbsp;ځکه چې هغۀ موسىٰ ته وفرمائيل چې، ”زۀ مالِک خُدائ يم او څوک چې زۀ غوره کړم زۀ هغوئ ته خپل رحم او ترس ښايم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27038, 'Romans 9:16', 'Romans', 9, 16, '&nbsp;نو دا د انسان په خواهش يا محنت باندې نۀ ده بلکې د خُدائ په رحم باندې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27039, 'Romans 9:17', 'Romans', 9, 17, '&nbsp;ځکه چې خُدائ پاک په خپل کلام کښې فِرعون ته فرمائى چې، ”خو ما تۀ د دې دپاره بادشاه کړې چې خپل طاقت ستا په ذريعه څرګند کړم او چې زما نوم په ټوله دُنيا کښې خور شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27040, 'Romans 9:18', 'Romans', 9, 18, '&nbsp;نو دا د خُدائ پاک رضا ده چې په چا رحم کوى، او د چا زړونه سختوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27041, 'Romans 9:19', 'Romans', 9, 19, '&nbsp;نو تۀ به ما ته وائې چې، ”بيا خُدائ پاک ولې مونږ ملامتوى ځکه چې څوک د هغۀ د مرضۍ مخالفت کولے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27042, 'Romans 9:20', 'Romans', 9, 20, '&nbsp;نه، داسې مۀ وايه، تۀ څوک يې چې خُدائ پاک سره بحث وکړې؟ ولې يو لوښے کُلال ته دا وئيلے شى چې تا زۀ په دې رنګ ولې جوړ کړے يم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27043, 'Romans 9:21', 'Romans', 9, 21, '&nbsp;ولې د کُلال دا حق نۀ وى چې هم د دغې ډيرى د خټې نه دوه لوښى جوړ کړى، يو د خاص استعمال دپاره او بل د عام استعمال دپاره؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27044, 'Romans 9:22', 'Romans', 9, 22, '&nbsp;خو کۀ د خُدائ پاک مرضى وه چې خپل غضب وښائى او خپل طاقت څرګند کړى نو ځکه يې د غضب هغه لوښو سره ډېر صبر وکړو چې د تباه کېدو دپاره تيار شوى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27045, 'Romans 9:23', 'Romans', 9, 23, '&nbsp;او څۀ چې هغۀ وکړل نو د دې دپاره يې وکړل چې خپل لوئ جلال په هغه خلقو ښکاره کړى په چا چې هغه رحم کوى او کوم چې هغۀ د اول نه د خپلې لويئ دپاره تيار کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27046, 'Romans 9:24', 'Romans', 9, 24, '&nbsp;مونږ هم په هغه خلقو کښې حساب يُو کوم چې د يهوديانو او غېر‌يهوديانو نه رابللے شوى دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27047, 'Romans 9:25', 'Romans', 9, 25, '&nbsp;لکه څنګه چې هغۀ د هوسيع په کِتاب کښې فرمائيلى دى چې، ”هغوئ څوک چې زما اُمت نۀ وو، هغوئ ته به زۀ خپل اُمت ووايم، او هغه چې زما محبوبه نۀ وه، هغې ته به خپله محبوبه ووايم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
