(27091, 'Romans 11:15', 'Romans', 11, 15, '&nbsp;ځکه کۀ د هغوئ رد کېدل د دُنيا پخلا کېدل شول نو د هغوئ بيا قبلېدل به مړو ته د ژوندون نه څۀ کم نۀ وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27092, 'Romans 11:16', 'Romans', 11, 16, '&nbsp;کۀ چرې دا د اوړو اولنۍ پيړه پاکه وه نو بيا نور ټول اوړۀ به هم پاک وى او کۀ د ونې جرړې پاکې وى نو بيا څانګې به هم پاکې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27093, 'Romans 11:17', 'Romans', 11, 17, '&nbsp;کۀ د زيتون ځينې څانګې پرېکړے شى، او د هغې په ځائ په کښې د ځنګلى زيتون يوه څانګه پيوند شى، نو بيا تاسو غېر‌يهوديان هم د دغه ځنګلى څانګې په شان يئ. لکه څنګه چې هغه د بلې ونې د جرړو نه طاقت حاصلوى نو هم دغه شان تاسو هم د يهوديانو د روحانى جرړو نه طاقت حاصلوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27094, 'Romans 11:18', 'Romans', 11, 18, '&nbsp;نو ځان د هغه څانګو نه اوچت مۀ ګڼه. کۀ تۀ ځان اوچت ګڼې نو ياد ساته چې دا تۀ نۀ يې چې جرړو له وده ورکوې بلکې دا جرړه ده چې تۀ پرې پايې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27095, 'Romans 11:19', 'Romans', 11, 19, '&nbsp;تۀ به وائې چې، ”څانګې د دې دپاره پرېکړے شوې چې زۀ په کښې پيوند کړے شم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27096, 'Romans 11:20', 'Romans', 11, 20, '&nbsp;دا رښتيا ده، هغوئ د خپلې بې‌ايمانۍ په وجه پرېکړے شوې خو تا د ايمان په وسيله خپل ځائ نيولے دے. نو کبر مۀ کوه بلکې يرېږه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27097, 'Romans 11:21', 'Romans', 11, 21, '&nbsp;ځکه کۀ چرې خُدائ پاک اصلى څانګې پرې نۀ ښودلې نو هغه به تا هم پرې نۀ ږدى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27098, 'Romans 11:22', 'Romans', 11, 22, '&nbsp;د خُدائ پاک د رحم او غضب خيال کوه. هغه په نافرمانو باندې خپل غضب نازلوى، خو څوک چې د هغۀ په رحم يقين ساتى هغه ورته خپل رحم ښائى. خو کۀ تاسو په هغۀ يقين نۀ کوئ نو تاسو به هم پرېکړے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27099, 'Romans 11:23', 'Romans', 11, 23, '&nbsp;او کۀ د بنى اِسرائيل څوک په بې‌ايمانۍ کښې پاتې نۀ شى نو هغوئ به بيا پيوند کړے شى، ځکه چې خُدائ پاک دا قدرت لرى چې هغوئ بيا پيوند کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(27100, 'Romans 11:24', 'Romans', 11, 24, '&nbsp;ځکه کۀ چرې تۀ د خپل ځنګلى زيتون د ونې نه راپرېکړے شوے يې او د خپل فطرت په خلاف د اصلى زيتون سره پيوند شوے يې نو بيا به هغه څانګې څومره په آسانه پيوند شى کومې چې د اصلى زيتون خپلې څانګې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');